28		err = tx.QueryRowContext(ctx,
29			`INSERT INTO charges (amount, currency, status) VALUES ($1, $2, $3)
30			 RETURNING id`, p.Amount, p.Currency, p.Status).Scan(&p.ID)
31		if err != nil {
