38			`INSERT INTO audit (charge_id, note) VALUES ($1, 'captured')`, p.ID)
39		if err != nil {
40			return Charge{}, fmt.Errorf("audit charge %d: %w", p.ID, err)
41		}
42		return p, tx.Commit()
43	}
