func TestListRejectsABadCurrencyAndQueriesNothing(t *testing.T) {
	for _, currency := range []string{"us", "usdd", "u5d", "US D", "123", "€€€"} {
		t.Run(currency, func(t *testing.T) {
			fake := &fakeCharges{}
			h := NewHandlers(fake, noReceipts{})
			req := httptest.NewRequest(http.MethodGet,
				"/charges?currency="+url.QueryEscape(currency), nil)
			rec := httptest.NewRecorder()

			h.list(rec, req)

			if rec.Code != http.StatusBadRequest {
				t.Fatalf("status = %d, want 400", rec.Code)
			}
			if len(fake.listed) != 0 {
				t.Fatalf("List was called %d time(s) for a rejected currency",
					len(fake.listed))
			}
		})
	}
}
